import {initMelody} from './melody-ui.js';
import {progressionPdf} from './pdf-export.js';
import {TEMPLATES,byId,uid,FLATS,SHARPS,FAMILIES,STYLES,LEVELS,pc,rootName,chordName,notesFor,describeNotes,keyboardSvg,makeItem,inRange,cleanProject,cleanItem,midiBytes,PRESETS,esc,spellNote,makeSickItem,sickRefFor,handSplitFor,labelFor,sourceOctFor} from './core.js';
import {POSITION_ORDERS,STUDY_QUALITIES,STUDY_TYPES,buildStudy} from './study.js';
import {DOCUMENT_SOURCES} from './supplements.js';
import {SICK_POSITIONS,SICK_CATEGORIES,TOP_DEGREES} from './sick.js';
import {Piano,SequencePlayer} from './audio.js';
const $=id=>document.getElementById(id),KEY='atelier-reharmonisation-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
let draft;try{draft=cleanProject(saved?.draft);}catch{draft=cleanProject({name:'Ma nouvelle progression',items:[],tempo:80});}
let projects=[];for(const p of (Array.isArray(saved?.projects)?saved.projects:[])){try{projects.push(cleanProject(p));}catch{}}
let favorites=new Set((saved?.favorites||[]).filter(x=>typeof x==='string'&&/^\w+:\d+$/.test(x)));
let filter={root:0,family:'major',variation:'',top:'',style:'',level:'',query:'',mode:'chord',favorites:false,position:'',source:'',sickCategory:'',sickTop:''};
let selected=makeItem('M08',0),flats=saved?.flats!==false,solfege=saved?.solfege!==false,activeIndex=-1,toastTimer,currentTab='explore',dirty=false;
let progressionPdfUrl=null;
const piano=new Piano(text=>$('audio-status').textContent=text);
const player=new SequencePlayer(piano,i=>{activeIndex=i;document.querySelectorAll('.sequence-row').forEach((n,j)=>n.classList.toggle('playing',i===j));},s=>{$('play-seq').textContent=s==='playing'?'♫':'▶';$('play-seq').disabled=s==='playing';$('pause-seq').disabled=s!=='playing';});
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,draft,projects,favorites:[...favorites],flats,solfege}));}catch{toast('Mémoire locale pleine : exportez une sauvegarde pour conserver vos modifications.');}}
function modified(){dirty=true;draft.updated=new Date().toISOString();persist();}
function favKey(item){return item.id+':'+item.root;}
function initControls(){
 $('bank-count').textContent=`${(TEMPLATES.length*12).toLocaleString('fr-FR')} positions à explorer`;
 const names=flats?FLATS:SHARPS;
 $('root-grid').innerHTML=(filter.mode==='melody'?`<button class="all ${filter.root===null?'selected':''}" data-root="all">Toutes les fondamentales</button>`:'')+names.map((n,i)=>`<button data-root="${i}" class="${filter.root===i?'selected':''}" aria-pressed="${filter.root===i}">${n}</button>`).join('');
 $('family-grid').innerHTML=(filter.mode==='melody'?`<button data-family="" class="${filter.family===''?'selected':''}">Toutes</button>`:'')+Object.entries(FAMILIES).map(([id,name])=>`<button data-family="${id}" class="${filter.family===id?'selected':''}" aria-pressed="${filter.family===id}">${name}</button>`).join('');
 const options='<option value="">Toutes les notes</option>'+names.map((n,i)=>`<option value="${i}">${n}</option>`).join('');
 $('top-note').innerHTML=options;$('top-note').value=filter.top;
 $('melody-note').innerHTML=names.map((n,i)=>`<option value="${i}">${n}</option>`).join('');$('melody-note').value=filter.top||0;
 $('melody-first').hidden=filter.mode!=='melody';$('top-filter').hidden=filter.mode==='melody';
 document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===filter.mode));
 $('accidentals').textContent=flats?'♭ Bémols':'♯ Dièses';
 const suffixes=[...new Set(filter.source==='schneider1'?SICK_POSITIONS.filter(s=>!filter.family||SICK_CATEGORIES[s.category].family===filter.family).map(s=>s.suffix):TEMPLATES.filter(t=>!filter.family||t.family===filter.family).map(t=>t.suffix))];if(filter.variation&&!suffixes.includes(filter.variation))filter.variation='';
 $('variation').innerHTML='<option value="">Toutes les couleurs</option>'+suffixes.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');$('variation').value=filter.variation;
 $('style').value=filter.style;$('level').value=filter.level;$('favorites-only').checked=filter.favorites;$('position-filter').innerHTML='<option value="">Toutes les dispositions</option>'+POSITION_ORDERS.map(p=>`<option value="${p}">Position ${p}</option>`).join('');$('position-filter').value=filter.position;$('source-filter').innerHTML='<option value="">Toute la banque</option>'+Object.entries(DOCUMENT_SOURCES).map(([id,s])=>`<option value="${id}">${s.label}</option>`).join('');$('source-filter').value=filter.source;
 $('sick-filters').hidden=filter.source!=='schneider1';
 $('sick-category').innerHTML='<option value="">Toutes les rubriques</option>'+Object.entries(SICK_CATEGORIES).map(([id,c])=>`<option value="${id}">${c.label}</option>`).join('');$('sick-category').value=filter.sickCategory;
 const tops=[...new Set(SICK_POSITIONS.filter(s=>!filter.sickCategory||s.category===filter.sickCategory).map(s=>s.topDegree))];if(filter.sickTop&&!tops.includes(filter.sickTop))filter.sickTop='';
 $('sick-top').innerHTML='<option value="">Tous les sommets</option>'+tops.map(d=>`<option value="${d}">${TOP_DEGREES[d]}</option>`).join('');$('sick-top').value=filter.sickTop;
}
const itemIdentity=i=>i?`${i.id}:${i.root}:${i.sickNumber||''}`:'';
function filtered(){const items=[];for(const t of TEMPLATES){
 if(filter.position&&!t.positions?.includes(filter.position)||filter.source&&!t.sourceRefs?.some(r=>r.id===filter.source)||filter.family&&t.family!==filter.family||filter.style&&t.style!==filter.style||filter.level&&t.level!==filter.level)continue;
 for(const ref of (filter.source==='schneider1'?t.sickRefs:[null])){
  if(ref&&(filter.sickCategory&&ref.category!==filter.sickCategory||filter.sickTop&&ref.topDegree!==filter.sickTop))continue;
  if(filter.variation&&(ref?.suffix||t.suffix)!==filter.variation)continue;
  for(let root=0;root<12;root++){
   if(filter.root!==null&&root!==filter.root)continue;
   const item=ref?makeSickItem(ref.number,root):makeItem(t.id,root);
   if(filter.top!==''&&pc(root+t.intervals.at(-1))!==Number(filter.top))continue;
   if(filter.favorites&&!favorites.has(favKey(item)))continue;
   const query=filter.query.toLocaleLowerCase('fr');
   if(query&&!`${chordName(item,flats)} ${labelFor(item)} ${t.label} ${t.comment} ${(t.positions||[]).join(' ')} ${t.degrees.join(' ')} ${ref?SICK_CATEGORIES[ref.category].label:''}`.toLocaleLowerCase('fr').includes(query))continue;
   items.push(item);
  }
 }
}return filter.source==='schneider1'?items.sort((a,b)=>a.sickNumber-b.sickNumber||a.root-b.root):items;}
function renderResults(keepSelection=false){const list=filtered();if(!keepSelection&&!list.some(i=>itemIdentity(i)===itemIdentity(selected))){if(list.length)selected={...list[0]};else selected=null;}
 $('results-count').textContent=`${list.length} voicing${list.length>1?'s':''} disponible${list.length>1?'s':''}`;
 $('results').innerHTML=list.length?list.map(i=>{const t=byId[i.id];return `<button class="result-item ${itemIdentity(selected)===itemIdentity(i)?'selected':''}" data-select="${i.id}" data-root="${i.root}" ${i.sickNumber?`data-sick-number="${i.sickNumber}"`:""} aria-pressed="${itemIdentity(selected)===itemIdentity(i)}"><span><b>${esc(chordName(i,flats))}${favorites.has(favKey(i))?' <span aria-label="favori">★</span>':''}</b><small>${esc(labelFor(i))}</small></span><span class="formula-preview">${t.degrees.map(esc).join(' · ')}</span></button>`;}).join(''):'<div class="empty">Aucun voicing avec ces critères.<br>Essayez une autre famille ou retirez un filtre.</div>';
 renderInspector();
}
function renderInspector(){
 updatePdfLink();
 if(!selected){$('inspector').innerHTML='<div class="no-voicing"><h2>Une autre piste ?</h2><p>Ajustez les filtres pour découvrir d’autres couleurs harmoniques.</p></div>';return;}
 const t=byId[selected.id],notes=describeNotes(selected,solfege,flats),top=notes.at(-1),isFav=favorites.has(favKey(selected));
 $('inspector').innerHTML=`<div class="section-kicker">LE VOICING À L’ÉCOUTE · ${esc(t.id)}</div><div class="voicing-title"><div><h2>${esc(chordName(selected,flats))}</h2><span class="badge">${STYLES[t.style]}</span><span class="badge">${LEVELS[t.level]}</span></div><div><button class="star ${isFav?'on':''}" id="favorite" aria-label="${isFav?'Retirer des favoris':'Ajouter aux favoris'}" aria-pressed="${isFav}">${isFav?'★':'☆'}</button></div></div><div class="voicing-sub">${esc(labelFor(selected))} <span style="float:right" class="top-voice">Voix supérieure <strong>${esc(top.name)}${top.oct}</strong> · ${esc(top.degree)}</span></div><div class="keyboard-wrap">${keyboardSvg(selected,{solfege,flats})}</div><div class="recipe"><span class="recipe-label">LA FORMULE</span>${notes.map(n=>`<span class="note-token"><strong>${esc(n.degree)}</strong><small>${esc(n.name)}${n.oct}</small></span>`).join('')}</div><div class="voicing-comment">${esc(sickRefFor(selected)?`Position ${selected.sickNumber} · ${SICK_CATEGORIES[sickRefFor(selected).category].label}. Comparez les voix intérieures en gardant la note supérieure.`:t.comment)}</div>${voicingContext(t,notes,selected)}<div class="inspector-tools"><label class="check-line"><input type="checkbox" id="chord-bass" ${selected.bass?'checked':''}> Ajouter la fondamentale à la basse</label><div class="octave-ctrl"><button id="oct-down" aria-label="Descendre le voicing d’une octave">−</button><span>${selected.oct>0?'+':''}${selected.oct} octave</span><button id="oct-up" aria-label="Monter le voicing d’une octave">+</button></div><button class="text-btn" id="note-language">${solfege?'Do Ré Mi':'C D E'}</button></div><div class="audio-actions"><button class="dark" id="play-chord">▶ Écouter l’accord</button><button class="secondary" id="arp-up">↗ Arpège montant</button><button class="secondary" id="arp-down">↘ Arpège descendant</button></div><button class="primary add-chord" id="add-chord">+ Ajouter à ma progression</button>`;
}
function voicingContext(t,notes,item){
 let html='',ref=sickRefFor(item),split=handSplitFor(item);
 if(ref)html+=`<div class="voicing-position">Sick Chords Vol. 1 · n°${ref.number} · p. ${ref.page} · ${esc(TOP_DEGREES[ref.topDegree])} au sommet</div><p class="source-register">Registre du PDF en ${esc(rootName(item.root,flats))}.${item.oct!==sourceOctFor(item)?` Octave ajustée : ${item.oct-sourceOctFor(item)>0?'+':''}${item.oct-sourceOctFor(item)} par rapport au relevé.`:''} Bleu : main gauche ; ocre : main droite. Les douze tonalités sont documentées. Orthographe des notes selon leur fonction harmonique.</p>${ref.notationNote?`<p class="notation-note">${esc(ref.notationNote)}</p>`:''}`;
 if(!ref&&t.positions?.length)html+=`<div class="voicing-position">Disposition ${t.positions.join(' / ')} · 2 notes par main</div>`;
 if(Number.isInteger(split)){html+=`<p class="hand-guide"><span>MG · ${notes.slice(0,split).map(n=>esc(n.name)+n.oct).join(' – ')||'libre'}${item.bass?' + basse':''}</span><span>MD · ${notes.slice(split).map(n=>esc(n.name)+n.oct).join(' – ')||'libre'}</span><small>${ref?'Répartition des portées du PDF ; adapter le geste à vos mains.':'Répartition indicative ; choisir un registre et une position confortables.'}</small></p>`;}
 const refs=ref?t.sourceRefs.filter(r=>r.id==='schneider1'&&r.page.includes('position '+ref.number+' ·')):t.sourceRefs;
 if(refs?.length)html+=`<div class="voicing-source">Repères : ${refs.map(r=>esc(DOCUMENT_SOURCES[r.id].label)+' · '+esc(r.page)).join('<br>')}</div>`;
 if(!ref&&t.sickRefs.length)html+=`<div class="source-links">Retrouver le relevé : ${t.sickRefs.map(r=>`<button class="text-btn" data-use-sick="${r.number}">Sick Chords n°${r.number}</button>`).join(' ')}</div>`;
 return html;
}
function documentSourcesHtml(){return `<h3>Compléments des documents fournis</h3><p>Les dispositions sont saisies en formules et les explications sont rédigées pour l’atelier. Les PDF et leurs pages ne sont pas redistribués dans le site. Les anciennes formules et leurs identifiants sont conservés ; les dispositions déjà présentes sont référencées plutôt que dupliquées.</p><ul>${Object.values(DOCUMENT_SOURCES).map(s=>`<li><strong>${esc(s.title)}</strong> — ${esc(s.detail)}</li>`).join('')}</ul><p>Les 129 positions Sick Chords Vol. 1 apportent 113 formules complémentaires ; 16 dispositions déjà présentes sont référencées sans doublon. Leur classement par rubrique et degré supérieur est accessible en choisissant cette source dans Explorer. Les petites formes à trois voix, les tétrades à six dispositions, les formes ouvertes, les superstructures et les positions statiques de block chords enrichissent aussi la banque. « Kenny Barron » et « Herbie Hancock » reprennent les appellations du document ; elles ne certifient pas une invention ou une transcription d’enregistrement. Quelques positions de block chords ne constituent pas un moteur d’harmonisation automatique d’une mélodie. L’onglet Étudier propose des suites générées, avec leurs références et objectifs.</p>`;}
function initStudy(){
 $('study-type').innerHTML=Object.entries(STUDY_TYPES).map(([id,s])=>`<option value="${id}">${s.label}</option>`).join('');
 $('study-root').innerHTML=FLATS.map((n,i)=>`<option value="${i}">${n}</option>`).join('');
 $('study-position').innerHTML=POSITION_ORDERS.map(p=>`<option>${p}</option>`).join('');
 $('study-quality').innerHTML=Object.entries(STUDY_QUALITIES).map(([id,q])=>`<option value="${id}">${q.label}</option>`).join('');
 $('study-sick-category').innerHTML=Object.entries(SICK_CATEGORIES).map(([id,c])=>`<option value="${id}">${c.label}</option>`).join('');
 $('study-sick-number').innerHTML=SICK_POSITIONS.map(r=>`<option value="${r.number}">n°${r.number} · ${r.suffix} · p. ${r.page}</option>`).join('');$('study-sick-number').value='13';
 updateStudyTops('9');renderStudyPreview();
}
function updateStudyTops(preferred=$('study-sick-top').value){const tops=[...new Set(SICK_POSITIONS.filter(r=>r.category===$('study-sick-category').value).map(r=>r.topDegree))];$('study-sick-top').innerHTML=tops.map(d=>`<option value="${d}">${TOP_DEGREES[d]}</option>`).join('');$('study-sick-top').value=tops.includes(preferred)?preferred:tops[0];} 
function studyConfig(){return {type:$('study-type').value,root:Number($('study-root').value),position:$('study-position').value,quality:$('study-quality').value,cycle:$('study-cycle').value,sickCategory:$('study-sick-category').value,sickTop:$('study-sick-top').value,sickNumber:Number($('study-sick-number').value)};}
function renderStudyPreview(){const c=studyConfig(),meta=STUDY_TYPES[c.type],p=buildStudy(c);
 $('study-position-label').hidden=!['qualities','cycle','diatonic'].includes(c.type);$('study-sick-category-label').hidden=c.type!=='sickTop';$('study-sick-top-label').hidden=c.type!=='sickTop';$('study-sick-number-label').hidden=c.type!=='sickCycle';$('study-quality-label').hidden=!['positions','cycle'].includes(c.type);$('study-cycle-label').hidden=!['cycle','cadence','sickCycle'].includes(c.type);
 $('study-preview').innerHTML=`<h2>${esc(meta.label)}</h2><p>${esc(meta.help)}</p><div class="study-chords">${p.items.map((i,n)=>`<span><small>${n+1}</small><b>${esc(chordName(i,flats))}</b><em>${esc(i.sickNumber?`n°${i.sickNumber} · p. ${sickRefFor(i).page}`:byId[i.id].positions?.[0]||byId[i.id].label)}</em></span>`).join('')}</div><p class="study-ref">${esc(meta.source)}</p>`;
}
function renderSequence(){
 $('progression-name').value=draft.name;$('tempo').value=draft.tempo;$('loop').checked=draft.loop;$('global-bass').checked=draft.globalBass;
 $('sequence').innerHTML=draft.items.length?draft.items.map((item,i)=>{const t=byId[item.id];return `<div class="sequence-row ${activeIndex===i?'playing':''}"><span class="seq-num">${String(i+1).padStart(2,'0')}</span><button class="seq-title" data-seq-action="inspect" data-index="${i}" title="Voir et écouter ce voicing"><b>${esc(chordName(item,flats,draft.globalBass))}</b><small>${esc(labelFor(item))}</small></button><span class="seq-formula">${describeNotes(item,solfege,flats).map(n=>esc(n.name)).join(' · ')}</span><div class="octave-ctrl"><button data-seq-action="octdown" data-index="${i}" aria-label="Descendre l’accord ${i+1} d’une octave">−</button><span>${item.oct>0?'+':''}${item.oct} oct.</span><button data-seq-action="octup" data-index="${i}" aria-label="Monter l’accord ${i+1} d’une octave">+</button></div><label class="seq-beats"><select data-beats="${i}" aria-label="Durée de l’accord ${i+1}">${Array.from({length:16},(_,j)=>(j+1)/2).map(n=>`<option value="${n}" ${item.beats===n?'selected':''}>${n}</option>`).join('')}</select> temps</label><label class="check-line seq-bass"><input type="checkbox" data-item-bass="${i}" ${item.bass?'checked':''} aria-label="Basse de l’accord ${i+1}"> Basse</label><div class="seq-actions"><button data-seq-action="up" data-index="${i}" ${i===0?'disabled':''} aria-label="Déplacer l’accord ${i+1} vers le haut">↑</button><button data-seq-action="down" data-index="${i}" ${i===draft.items.length-1?'disabled':''} aria-label="Déplacer l’accord ${i+1} vers le bas">↓</button><button data-seq-action="duplicate" data-index="${i}" aria-label="Dupliquer l’accord ${i+1}">⧉</button><button class="danger" data-seq-action="remove" data-index="${i}" aria-label="Supprimer l’accord ${i+1}">✕</button></div></div>`;}).join(''):'<div class="empty">Commencez par un voicing qui vous plaît.<br>Le bouton « Ajouter à ma progression » le place ici.</div>';
 const beats=draft.items.reduce((n,i)=>n+i.beats,0),seconds=Math.round(beats*60/draft.tempo);
 $('seq-summary').textContent=draft.items.length?`${draft.items.length} accord${draft.items.length>1?'s':''} · ${beats} temps · ${Math.floor(seconds/60)} min ${String(seconds%60).padStart(2,'0')} s`:'Votre progression attend son premier accord.';
 updatePdfLink();$('play-seq').disabled=!draft.items.length||player.state==='playing';$('pause-seq').disabled=player.state!=='playing';$('midi-export').disabled=!draft.items.length;
}
function tab(name){currentTab=name;for(const n of ['explore','melody','study','projects','learn'])$(n+'-view').hidden=n!==name;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));if(name==='projects')renderProjects();if(name!=='explore')player.stop();if(name!=='melody')melodyController?.stop();window.scrollTo({top:0,behavior:'smooth'});}
function renderProjects(){
 $('project-count').textContent=projects.length?`(${projects.length})`:'';
 $('projects-list').innerHTML=projects.length?projects.toSorted((a,b)=>b.updated.localeCompare(a.updated)).map(p=>`<article class="project-card card"><div class="section-kicker">${p.items.length} ACCORDS · ${p.tempo} BPM</div><h2>${esc(p.name)}</h2><p>Modifiée le ${new Date(p.updated).toLocaleDateString('fr-FR')}</p><div class="project-chords">${p.items.slice(0,8).map(i=>esc(chordName(i,flats))).join(' <span style="color:#a5ae9b">→</span> ')}${p.items.length>8?' …':''}</div><div class="row"><button class="dark" data-open-project="${esc(p.id)}">Ouvrir</button><button class="text-btn" data-export-project="${esc(p.id)}">Exporter</button><button class="text-btn danger" data-delete-project="${esc(p.id)}">Supprimer</button></div></article>`).join(''):'<div class="empty card">Vos progressions enregistrées apparaîtront ici.<br>Composez une suite d’accords, puis cliquez sur « Enregistrer ».</div>';
}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function slug(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,70)||'progression';}
function exportBackup(){download(`atelier-reharmonisation-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({app:'atelier-reharmonisation',version:1,melody:melodyController.getState(),exported:new Date().toISOString(),draft,projects,favorites:[...favorites],flats,solfege},null,2),'application/json');toast('Sauvegarde exportée : conservez ce fichier pour changer d’appareil.');}
async function preview(arp=0,item=selected){if(!item)return;melodyController?.stop();try{player.stop();await piano.init();piano.master.gain.value=.65;piano.hush();piano.playChord(notesFor(item,draft.items.includes(item)&&draft.globalBass),{duration:2,arp});}catch(e){toast('Le son n’a pas pu démarrer. Réessayez depuis un bouton de lecture.');}}
function changeOct(delta){if(!selected)return;const n={...selected,oct:selected.oct+delta};if(!inRange(n)){toast('Ce déplacement dépasse le registre du piano (88 touches).');return;}selected=n;renderInspector();}
function transpose(delta){player.stop();const items=draft.items.map(i=>{const n=i.root+delta;return {...i,root:pc(n),oct:i.oct+Math.floor(n/12)};});if(!items.every(i=>inRange(i,draft.globalBass))){toast('La transposition dépasserait le registre du piano.');return;}draft.items=items;modified();renderSequence();}
function updatePdfLink(){const items=draft.items.length?draft.items:selected?[{...selected,beats:4}]:[];if(progressionPdfUrl)URL.revokeObjectURL(progressionPdfUrl);progressionPdfUrl=URL.createObjectURL(new Blob([progressionPdf({name:draft.items.length?draft.name:'Fiche voicing',items,tempo:draft.tempo,globalBass:!!draft.items.length&&draft.globalBass,flats})],{type:'application/pdf'}));$('print').href=progressionPdfUrl;$('print').download=slug(draft.items.length?draft.name:'fiche-voicing')+'.pdf';}
function printProgression(){const items=draft.items.length?draft.items:selected?[{...selected,beats:4}]:[];if(!items.length){toast('Choisissez un voicing.');return;}try{download(slug(draft.items.length?draft.name:'fiche-voicing')+'.pdf',progressionPdf({name:draft.items.length?draft.name:'Fiche voicing',items,tempo:draft.tempo,globalBass:!!draft.items.length&&draft.globalBass,flats}),'application/pdf');toast('PDF téléchargé avec les accords et les claviers.');}catch(err){toast('Export PDF impossible : '+err.message);}}
function renderLearning(){const lessons=[
 ['Commencer par la mélodie','Chaque voicing possède une note supérieure qui s’entend comme une mélodie. Dans « Une note de mélodie », choisissez cette note : l’atelier cherche toutes les dispositions qui la placent au sommet. Écoutez ensuite les accords voisins pour choisir une direction.','Une note au sommet → plusieurs harmonies possibles'],
 ['Les coquilles : l’essentiel de l’accord','La tierce et la septième donnent l’identité d’un accord. Avec la fondamentale, elles constituent une coquille simple. Travaillez d’abord les changements lentement ; ajoutez ensuite une neuvième ou une treizième.','C7 : Do – Mi – Si♭'],
 ['Rootless A et B','Ces formes omettent la fondamentale. La forme A part souvent de la tierce ; la forme B de la septième. Alterner A et B peut rapprocher les voix dans un II–V–I. Avec une basse ajoutée, leur fonction devient plus évidente.','Dm9 → G13 → Cmaj9'],
 ['Des degrés pour transposer','La formule donne les notes du grave à l’aigu relativement à la fondamentale. 9 désigne la seconde à l’octave, 11 la quarte et 13 la sixte. L’atelier conserve leur orthographe : ♯9 et ♭3 peuvent sonner pareil tout en ayant des fonctions différentes.','Cmaj9 : 3 – 5 – 7 – 9 → Mi – Sol – Si – Ré'],
 ['Quartes, superstructures et accords suspendus','Les quartes donnent une couleur ouverte. Les superstructures empilent un accord simple au-dessus des notes guides. Pour une couleur gospel 13sus, une basse de Sol sous Fa–La–Do–Mi suffit à ouvrir tout un paysage.','G13sus : Sol + Fa – La – Do – Mi'],
 ['La conduite des voix se choisit à l’oreille','Comparez la note supérieure et le déplacement des notes intermédiaires. Changez l’octave d’un accord pour éviter de grands sauts. L’atelier vous laisse choisir : il ne calcule pas automatiquement une « meilleure » réharmonisation.','Écouter → comparer → ajuster → rejouer']
 ];$('learning').innerHTML=lessons.map(([title,text,example],i)=>`<article class="learn-card card"><div class="section-kicker">REPÈRE ${String(i+1).padStart(2,'0')}</div><h2>${title}</h2><p>${text}</p><div class="example">${example}</div></article>`).join('');
 $('sources').innerHTML=`<h2>La banque, les sources et les crédits</h2><p><strong>${TEMPLATES.length} formules documentées × 12 fondamentales = ${TEMPLATES.length*12} positions.</strong> Ces constructions couvrent des usages courants du jazz, de la soul et du gospel. Elles ne constituent ni une mesure statistique des voicings les plus joués, ni une reproduction exhaustive du catalogue commercial Sick Chords. Les 129 positions du volume 1 fourni par l’utilisateur sont repérées séparément ; les autres volumes et le contenu complet de Sick Chords Lab ne sont pas couverts. Les noms de musiciens désignent des traditions stylistiques, pas des transcriptions attribuées.</p>${documentSourcesHtml()}<h3>Ressources de Jeff Schneider</h3><ul><li><a href="https://www.youtube.com/watch?v=A4US0VFrF9Q" target="_blank" rel="noopener">La démonstration Sick Chords Lab</a> et <a href="https://go.jeffschneidermusic.com/sick-chords-everything-bundle" target="_blank" rel="noopener">sa présentation officielle</a> : point de départ fonctionnel. La transcription n’a pas pu être récupérée ; l’exhaustivité par rapport à la vidéo n’est pas certifiée.</li><li><a href="https://jeffschneidermusic.com/blog/how-to-make-simple-chords-sound-extraordinary" target="_blank" rel="noopener">Note supérieure et mélodie implicite</a>.</li><li><a href="https://jeffschneidermusic.com/blog/chord-stacking" target="_blank" rel="noopener">Chord stacking : empiler des accords simples</a>.</li><li><a href="https://jeffschneidermusic.com/blog/bieber-plays-my-favorite-gospel-chord" target="_blank" rel="noopener">La couleur 13sus gospel</a>, <a href="https://jeffschneidermusic.com/blog/x-add9-over-3" target="_blank" rel="noopener">add9 avec tierce à la basse</a> et <a href="https://jeffschneidermusic.com/blog/c7sus4add-3" target="_blank" rel="noopener">sus4 avec tierce ajoutée au-dessus de la quarte</a>.</li></ul><h3>Fondamentaux du piano jazz</h3><ul><li><a href="https://www.openstudiojazz.com/courses/jazz-chords-for-beginners/" target="_blank" rel="noopener">Open Studio / Adam Maness — voicings avec fondamentale, sans fondamentale et d’accompagnement</a>.</li><li><a href="https://www.openstudiojazz.com/courses/jazz-piano-basics-vol-2-left-hand-voicings/" target="_blank" rel="noopener">Open Studio — coquilles, enrichissements et quartes à la main gauche</a>.</li></ul><h3>Son de piano et fonctionnement</h3><p>Enregistrements <a href="https://github.com/sfzinstruments/SalamanderGrandPiano" target="_blank" rel="noopener">Salamander Grand Piano v3, Alexander Holm</a>, sous <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>. Distribution MP3 du projet <a href="https://github.com/Tonejs/audio/tree/master/salamander" target="_blank" rel="noopener">Tone.js audio</a>. Une couche dynamique, transposition des échantillons voisins, enveloppe et mixage dans l’application. L’ensemble des 16 couches de la banque d’origine n’est pas utilisé.</p><p>Vos progressions, favoris et le brouillon sont enregistrés automatiquement dans ce navigateur. « Enregistrer » conserve une progression dans le carnet. « Sauvegarder » exporte un fichier JSON pour un autre appareil. L’export MIDI comprend les notes, le tempo et les durées ; le téléchargement PDF propose une fiche avec claviers, notes et formules, sans fenêtre d’impression. Les fonctions de carnet, sauvegarde et export MIDI sont propres à cet atelier.</p><p>Sur iPad, démarrez le son avec un bouton de lecture. Les touches du clavier peuvent être écoutées individuellement. Convention : le Do central est C4 (MIDI 60).</p>`;
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.tab){tab(button.dataset.tab);return;}
 if(button.dataset.mode){filter.mode=button.dataset.mode;filter.top=filter.mode==='melody'?'0':'';filter.root=filter.mode==='melody'?null:0;filter.family=filter.mode==='melody'?'':'major';filter.variation='';initControls();renderResults();return;}
 if(button.closest('#root-grid')){filter.root=button.dataset.root==='all'?null:Number(button.dataset.root);initControls();renderResults();return;}
 if('family'in button.dataset){filter.family=button.dataset.family;if(filter.sickCategory&&SICK_CATEGORIES[filter.sickCategory].family!==filter.family)filter.sickCategory='';filter.variation='';initControls();renderResults();return;}
 if(button.dataset.useSick){selected=makeSickItem(Number(button.dataset.useSick),selected.root);renderResults(true);return;}
 if(button.dataset.select){selected=button.dataset.sickNumber?makeSickItem(Number(button.dataset.sickNumber),Number(button.dataset.root)):makeItem(button.dataset.select,Number(button.dataset.root));renderResults(true);return;}
 if(button.dataset.seqAction){const i=Number(button.dataset.index),item=draft.items[i];if(!item)return;const action=button.dataset.seqAction;if(action==='inspect'){selected={...item};renderInspector();await preview(0,item);$('inspector').scrollIntoView({behavior:'smooth',block:'center'});return;}player.stop();if(action==='remove')draft.items.splice(i,1);if(action==='duplicate'){if(draft.items.length>=256){toast('La progression est limitée à 256 accords.');return;}draft.items.splice(i+1,0,{...item});}if(action==='up'&&i>0)[draft.items[i-1],draft.items[i]]=[draft.items[i],draft.items[i-1]];if(action==='down'&&i<draft.items.length-1)[draft.items[i+1],draft.items[i]]=[draft.items[i],draft.items[i+1]];if(action==='octup'||action==='octdown'){const next={...item,oct:item.oct+(action==='octup'?1:-1)};if(!inRange(next,draft.globalBass)){toast('Ce déplacement dépasse le registre du piano.');return;}draft.items[i]=next;}modified();renderSequence();return;}
 if(button.dataset.openProject){if(dirty&&draft.items.length&&!confirm('Ouvrir cette progression ? Le brouillon actuel sera remplacé. Enregistrez-le d’abord si vous souhaitez le conserver.'))return;player.stop();draft=structuredClone(projects.find(p=>p.id===button.dataset.openProject));dirty=false;persist();renderSequence();tab('explore');$('progression-section').scrollIntoView({behavior:'smooth'});return;}
 if(button.dataset.deleteProject){const p=projects.find(p=>p.id===button.dataset.deleteProject);if(confirm(`Supprimer « ${p.name} » du carnet ?`)){projects=projects.filter(x=>x.id!==p.id);persist();renderProjects();}return;}
 if(button.dataset.exportProject){const p=projects.find(p=>p.id===button.dataset.exportProject);download(slug(p.name)+'.json',JSON.stringify({app:'atelier-reharmonisation',version:1,projects:[p]},null,2),'application/json');return;}
 if(button.dataset.preset!==undefined){const p=PRESETS[Number(button.dataset.preset)];player.stop();draft=cleanProject({...p,items:structuredClone(p.items)});modified();renderSequence();$('preset-dialog').close();toast('Exemple chargé. Modifiez-le à votre rythme.');return;}
 switch(button.id){
 case'accidentals':flats=!flats;initControls();renderResults(true);renderSequence();persist();break;
 case'note-language':solfege=!solfege;renderInspector();renderSequence();persist();break;
 case'favorite':{const key=favKey(selected);favorites.has(key)?favorites.delete(key):favorites.add(key);persist();renderResults(true);break;}
 case'oct-down':changeOct(-1);break;case'oct-up':changeOct(1);break;
 case'play-chord':await preview();break;case'arp-up':await preview(.2);break;case'arp-down':await preview(-.2);break;
 case'add-chord':if(draft.items.length>=256){toast('La progression est limitée à 256 accords.');break;}if(!inRange(selected,draft.globalBass)){toast('La basse globale dépasserait le registre du piano.');break;}player.stop();draft.items.push({...selected,beats:4});modified();renderSequence();toast(`${chordName(selected,flats)} ajouté à la progression.`);break;
 case'reset':filter={root:0,family:'major',variation:'',top:'',style:'',level:'',query:'',mode:'chord',favorites:false,position:'',source:'',sickCategory:'',sickTop:''};$('search').value='';initControls();renderResults();break;
 case'surprise':{const list=filtered();if(!list.length){toast('Retirez un filtre pour retrouver des propositions.');break;}selected={...list[Math.floor(Math.random()*list.length)]};renderResults(true);await preview();break;}
 case'play-seq':melodyController?.stop();if(piano.master)piano.master.gain.value=.65;try{if(draft.items.length){$('play-seq').disabled=true;await player.play(draft.items.map(i=>({...i,notes:notesFor(i,draft.globalBass)})),draft.tempo,draft.globalBass,draft.loop);}}catch{toast('Impossible de démarrer le son. Réessayez.');$('play-seq').disabled=false;}break;
 case'pause-seq':player.pause();break;case'stop-seq':player.stop();break;
 case'transpose-up':transpose(1);break;case'transpose-down':transpose(-1);break;
 case'clear-seq':if(!draft.items.length||confirm('Vider le brouillon de progression affiché ?')){player.stop();draft.items=[];modified();renderSequence();}break;
 case'save-project':{if(!draft.items.length){toast('Ajoutez au moins un accord avant d’enregistrer.');break;}draft.name=$('progression-name').value.trim()||'Ma progression';draft.updated=new Date().toISOString();const i=projects.findIndex(p=>p.id===draft.id);if(i<0)projects.push(structuredClone(draft));else projects[i]=structuredClone(draft);dirty=false;persist();renderProjects();toast('Progression enregistrée dans votre carnet.');break;}
 case'new-project':if(dirty&&draft.items.length&&!confirm('Commencer une nouvelle progression ? Le brouillon actuel sera remplacé.'))break;player.stop();draft=cleanProject({name:'Ma nouvelle progression',items:[],tempo:80});dirty=false;persist();renderSequence();tab('explore');break;
 case'backup':exportBackup();break;case'import':$('import-file').click();break;
 case'midi-export':if(draft.items.length){download(slug(draft.name)+'.mid',midiBytes(draft.items,draft.tempo,draft.globalBass),'audio/midi');toast('MIDI exporté : notes, durées et tempo inclus.');}break;
 case'print':printProgression();break;
 case'study-load':if(draft.items.length&&!confirm('Remplacer le brouillon affiché par cet exercice ? Les progressions déjà enregistrées sont conservées.'))break;player.stop();draft=cleanProject(buildStudy(studyConfig()));modified();renderSequence();tab('explore');$('progression-section').scrollIntoView({behavior:'smooth'});toast('Exercice chargé : vous pouvez l’écouter, l’adapter ou l’enregistrer.');break;
 case'preset':$('preset-list').innerHTML=PRESETS.map((p,i)=>`<button type="button" class="preset-item" data-preset="${i}"><strong>${p.name}</strong><small>${p.detail}</small></button>`).join('');$('preset-dialog').showModal();break;
 }
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.id==='position-filter'){filter.position=el.value;renderResults();}if(el.id==='source-filter'){filter.source=el.value;initControls();renderResults();}if(el.id==='sick-category'){filter.sickCategory=el.value;if(el.value)filter.family=SICK_CATEGORIES[el.value].family;filter.variation='';initControls();renderResults();}if(el.id==='sick-top'){filter.sickTop=el.value;renderResults();}if(el.id==='study-sick-category')updateStudyTops();if(el.id.startsWith('study-'))renderStudyPreview();
 if(el.id==='variation'){filter.variation=el.value;renderResults();}if(el.id==='top-note'||el.id==='melody-note'){filter.top=el.value;renderResults();}if(el.id==='style'){filter.style=el.value;renderResults();}if(el.id==='level'){filter.level=el.value;renderResults();}if(el.id==='favorites-only'){filter.favorites=el.checked;renderResults();}
 if(el.id==='chord-bass'){const next={...selected,bass:el.checked};if(!inRange(next)){el.checked=false;toast('La basse serait hors du registre du piano.');return;}selected=next;renderInspector();}
 if(el.id==='tempo'){player.stop();draft.tempo=Math.min(240,Math.max(30,Number(el.value)||80));modified();renderSequence();}
 if(el.id==='loop'){draft.loop=el.checked;player.loop=el.checked;modified();}
 if(el.id==='global-bass'){if(el.checked&&!draft.items.every(i=>inRange(i,true))){el.checked=false;toast('La basse sortirait du registre pour un des accords.');return;}player.stop();draft.globalBass=el.checked;modified();renderSequence();}
 if(el.dataset.beats!==undefined){player.stop();draft.items[Number(el.dataset.beats)].beats=Number(el.value);modified();renderSequence();}
 if(el.dataset.itemBass!==undefined){const i=Number(el.dataset.itemBass);const n={...draft.items[i],bass:el.checked};if(!inRange(n)){el.checked=false;toast('La basse serait hors du registre du piano.');return;}player.stop();draft.items[i]=n;modified();renderSequence();}
});
$('search').addEventListener('input',e=>{filter.query=e.target.value;renderResults();});
$('progression-name').addEventListener('input',e=>{draft.name=e.target.value;modified();updatePdfLink();});
$('inspector').addEventListener('click',async e=>{const key=e.target.closest('[data-midi]');if(!key)return;try{await piano.init();piano.playNote(Number(key.dataset.midi));key.classList.add('key-pressed');setTimeout(()=>key.classList.remove('key-pressed'),400);}catch{toast('Le son est indisponible.');}});
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Le fichier est trop volumineux (2 Mo maximum).');const input=JSON.parse(await file.text());if(input.app!=='atelier-reharmonisation'||input.version!==1)throw Error('Ce fichier n’est pas une sauvegarde compatible.');if(!Array.isArray(input.projects)||input.projects.length>500)throw Error('La liste de progressions est invalide.');const incoming=input.projects.map(cleanProject);const sameMusicalContent=(a,b)=>JSON.stringify([a.name,a.tempo,a.globalBass,a.loop,a.items])===JSON.stringify([b.name,b.tempo,b.globalBass,b.loop,b.items]);let importedDraft=input.draft?cleanProject(input.draft):null;if(importedDraft?.items.length&&!incoming.some(p=>sameMusicalContent(p,importedDraft))&&!projects.some(p=>sameMusicalContent(p,importedDraft))){importedDraft={...importedDraft,id:uid(),name:importedDraft.name+' (brouillon importé)'};incoming.push(importedDraft);}let importedCount=0;for(const p of incoming){const index=projects.findIndex(x=>x.id===p.id);if(index>=0&&JSON.stringify([projects[index].name,projects[index].tempo,projects[index].globalBass,projects[index].loop,projects[index].items])!==JSON.stringify([p.name,p.tempo,p.globalBass,p.loop,p.items]))p.id=uid();if(!projects.some(x=>x.id===p.id)){projects.push(p);importedCount++;}}if(Array.isArray(input.favorites))input.favorites.filter(x=>typeof x==='string'&&/^\w+:\d+$/.test(x)).forEach(x=>favorites.add(x));if(input.melody)melodyController.importState(input.melody);persist();renderProjects();renderResults(true);toast(`${importedCount} progression(s) ajoutée(s). Le brouillon actuel est conservé.`);}catch(err){toast('Import impossible : '+err.message);}finally{e.target.value='';}});
$('inspector').addEventListener('keydown',e=>{if(e.target.matches('[data-midi]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
window.addEventListener('pagehide',()=>player.stop());
initControls();renderResults();renderSequence();renderProjects();renderLearning();initStudy();persist();

const melodyController=initMelody({piano,stopOther:()=>player.stop(),toast,download,settings:()=>({flats,solfege}),loadProgression:p=>{if(draft.items.length&&!confirm('Remplacer le brouillon par ces accords ? Les progressions enregistrées sont conservées.'))return;player.stop();draft=p;modified();renderSequence();tab('explore');$('progression-section').scrollIntoView({behavior:'smooth'});}});
